22	$resolvePositiveInt = static function ($value, int $default, int $min = 1, ?int $max = null): int {
23	    $validated = filter_var($value, FILTER_VALIDATE_INT);
24	    if ($validated === false) {
25	        return $default;
26	    }
27	
28	    $normalized = max($min, (int) $validated);
29	    if ($max === null) {
30	        return $normalized;
31	    }
32	
33	    return min($max, $normalized);
34	};
