172	$insideListHandler = static function (
173	        Request $req,
174	        int $boardNo,
175	        string $viewName,
176	        string $listRouteName
177	    ) use ($resolvePositiveInt): string {
178	        $page = $resolvePositiveInt($req->query('page', 1), 1);
179	        $categoryRaw = $req->query('category');
180	        $categoryNo = null;
181	        if ($categoryRaw !== null && $categoryRaw !== '') {
182	            $cv = filter_var($categoryRaw, FILTER_VALIDATE_INT);
183	            if ($cv !== false && (int) $cv > 0) {
184	                $categoryNo = (int) $cv;
185	            }
186	        }
187	        $q = trim((string) $req->query('q', ''));
188	        $list = inside_board_list(
189	            $boardNo,
190	            $page,
191	            $categoryNo,
192	            $q !== '' ? $q : null
193	        );
194	
195	        $listUrl = route($listRouteName, [], false);
196	        $mergeQuery = static function (array $extra) use ($q): array {
197	            $p = $extra;
198	            if ($q !== '') {
199	                $p['q'] = $q;
200	            }
201	
202	            return array_filter(
203	                $p,
204	                static fn ($v) => $v !== null && $v !== ''
205	            );
206	        };
207	
208	        $categoryItems = [];
209	        $manage = inside_board_manage($boardNo);
210	        $catEnabled = ($manage['category_yn'] ?? 'N') === 'Y';
211	        $allQuery = $mergeQuery([]);
212	        $categoryItems[] = [
213	            'label' => 'ALL',
214	            'href' => $listUrl . ($allQuery !== [] ? '?' . http_build_query($allQuery) : ''),
215	            'active' => $categoryNo === null,
216	        ];
217	        if ($catEnabled) {
218	            foreach (inside_board_categories($boardNo) as $row) {
219	                $cn = (int) ($row['no'] ?? 0);
220	                if ($cn < 1) {
221	                    continue;
222	                }
223	                $cq = $mergeQuery(['category' => $cn]);
224	                $categoryItems[] = [
225	                    'label' => (string) ($row['name'] ?? ''),
226	                    'href' => $listUrl . '?' . http_build_query($cq),
227	                    'active' => $categoryNo === $cn,
228	                ];
229	            }
230	        }
231	
232	        $paginationQuery = $mergeQuery([]);
233	
234	        return render($viewName, [
235	            'pageType' => 'inside',
236	            'boardNo' => $boardNo,
237	            'posts' => $list['rows'],
238	            'paginationTotal' => $list['totalPages'],
239	            'paginationCurrent' => $list['page'],
240	            'paginationQueryParams' => $paginationQuery,
241	            'categoryItems' => $categoryItems,
242	            'searchQuery' => $q,
243	            'listRouteName' => $listRouteName,
244	            'activeCategoryNo' => $categoryNo,
245	        ]);
246	};
